module heating_system_controller (
        input clk,
        input areset,
        input temp_low,
        input temp_high,
        output reg heater_on);parameter Heat_Off=1'b0, Heat_On=1'b1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Heat_Off;
		else begin
			case (state)
				Heat_Off: state <= temp_low ? Heat_On : Heat_Off;
				Heat_On: state <= temp_high ? Heat_Off : Heat_On;
			endcase
		end
	end

	assign heater_on = (state == Heat_On);

endmodule

