module down_counter_with_clear_14bit (
    input wire clk,
    input wire clr,
    output reg [13:0] count
);

    always @(posedge clk or posedge clr) begin
        if (clr) begin
            count <= 14'b00000000000000;
        end else begin
            count <= count - 1;
        end
    end

endmodule

