module top_module(
  input wire clk,
  output reg red,
  output reg yellow,
  output reg green
);//-- Definir los estados de la maquina de estados
parameter [1:0] GREEN = 2'b00;
parameter [1:0] YELLOW = 2'b01;
parameter [1:0] RED = 2'b10;

//-- Definir los tiempos de cada estado
parameter GREEN_TIME = 60_000_000; //-- 60 segundos
parameter YELLOW_TIME = 10_000_000; //-- 10 segundos
parameter RED_TIME = 50_000_000; //-- 50 segundos

//-- Definir el registro de estado
reg [1:0] state;

//-- Definir el contador de tiempo
reg [31:0] counter;

//-- Inicializar el registro y el contador
initial begin
  state = GREEN;
  counter = GREEN_TIME;
end

//-- Implementar la maquina de estados
always @(posedge clk) begin
  case (state)
    GREEN: begin
      green <= 1'b1;
      yellow <= 1'b0;
      red <= 1'b0;
      if (counter == 1) begin
        state <= YELLOW;
        counter <= YELLOW_TIME;
      end else begin
        counter <= counter - 1;
      end
    end
    YELLOW: begin
      green <= 1'b0;
      yellow <= 1'b1;
      red <= 1'b0;
      if (counter == 1) begin
        state <= RED;
        counter <= RED_TIME;
      end else begin
        counter <= counter - 1;
      end
    end
    RED: begin
      green <= 1'b0;
      yellow <= 1'b0;
      red <= 1'b1;
      if (counter == 1) begin
        state <= GREEN;
        counter <= GREEN_TIME;
      end else begin
        counter <= counter - 1;
      end
    end
  endcase
end

endmodule

