    output reg tb_tx_busy,
    output reg [7:0] tb_tx_data
);reg [7:0] buffer;
reg [2:0] buffer_count;
reg [2:0] transmit_count;
reg [7:0] transmit_data;

always @(posedge clk) begin
    if (rst) begin
        buffer_count <= 0;
        transmit_count <= 0;
        tb_tx_start <= 0;
        tb_tx_busy <= 0;
        tb_tx_data <= 0;
