            transmit_data <= buffer[transmit_count];
            tb_tx_data <= transmit_data;
            transmit_count <= transmit_count + 1;
            buffer_count <= buffer_count - 1;
            tb_tx_start <= 0;
            tb_tx_busy <= 1;
        end

        if (tb_tx_busy) begin
            tb_tx_busy <= 0;
        end
    end
end

