module top_module(
    input CLK, EN, TE,
    input [31:0] D,
    output reg [31:0] Q,
    output ENCLK
);reg gated_clk;
    reg [31:0] d_ff;

    always @ (posedge CLK) begin
        if (EN) begin
            gated_clk <= CLK;
            d_ff <= D;
        end
    end

    always @ (posedge gated_clk) begin
        Q <= d_ff;
    end

    assign ENCLK = gated_clk & EN;

endmodule

