description:
Design a 3-to-8 priority decoder that generates a unique output line for each combination of the 3 input signals. The output is an active high signal corresponding to the binary value of the input, with the output lines being set from `out[0]` for `in=3'b000` to `out[7]` for `in=3'b111`. If an invalid input is received, all outputs are set to low.
module top_module(
  input [n-1:0] in,
  output [m-1:0] out
);

code:
module top_module(
  input [n-1:0] in,
  output [m-1:0] out
);parameter n = 3; // number of input signals
parameter m = 8; // number of output signals

reg [m-1:0] out_reg;

always @(*) begin
  case(in)
    3'b000: out_reg = 8'b00000001;
    3'b001: out_reg = 8'b00000010;
    3'b010: out_reg = 8'b00000100;
    3'b011: out_reg = 8'b00001000;
    3'b100: out_reg = 8'b00010000;
    3'b101: out_reg = 8'b00100000;
    3'b110: out_reg = 8'b01000000;
    3'b111: out_reg = 8'b10000000;
    default: out_reg = 8'b00000000;
  endcase
end

assign out = out_reg;

endmodule

