module top_module(
  input clk,
  input reset,
  input in1,
  output reg out
);// Define the three states
  parameter IDLE = 2'd0;
  parameter FIRST_HIGH = 2'd1;
  parameter SECOND_HIGH = 2'd2;

  // Define the current state and next state variables
  reg [1:0] state, next_state;

  // Define the count variable to keep track of the number of high signals detected
  reg [1:0] count;

  // Define the output signal
  reg out_reg;

  // Assign the initial state and next state
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      state <= IDLE;
      next_state <= IDLE;
      count <= 2'd0;
      out_reg <= 1'b0;
    end
    else begin
      state <= next_state;
    end
  end

  // Define the state transition logic
  always @ (state, in1) begin
    case (state)
      IDLE: begin
        if (in1 == 1'b1) begin
          next_state <= FIRST_HIGH;
          count <= 2'd1;
        end
        else begin
          next_state <= IDLE;
          count <= 2'd0;
        end
      end
      FIRST_HIGH: begin
        if (in1 == 1'b1) begin
          next_state <= SECOND_HIGH;
          count <= 2'd2;
        end
        else begin
          next_state <= IDLE;
          count <= 2'd0;
        end
      end
      SECOND_HIGH: begin
        if (in1 == 1'b1) begin
          next_state <= IDLE;
          count <= 2'd0;
          out_reg <= 1'b1;
        end
        else begin
          next_state <= IDLE;
          count <= 2'd0;
        end
      end
      default: next_state <= IDLE;
    endcase
  end

  // Assign the output signal
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      out <= 1'b0;
    end
    else begin
      out <= out_reg;
    end
  end

endmodule

