module top_module(clk, reset, modulus, time_delay, cout);// INPUT PORTS
    input clk;
    input reset;
    input [31:0] modulus;
    input [31:0] time_delay;

    // OUTPUT PORTS
    output reg cout;

    // INTERNAL VARIABLES AND NETS
    reg [31:0] count;
    reg tmp_cout;
    reg first_rising_edge;
    reg clk_last_value;
    reg clk_last_valid_value;
    reg cout_tmp;

    always @(posedge clk or posedge reset)
    begin
        if (reset)
        begin
            count <= 1;
            tmp_cout <= 0;
            first_rising_edge <= 1;
        end
        else begin
            if (clk_last_value !== clk)
            begin
                if (clk === 1'bx)
                begin
                    $display("Warning : Invalid transition to 'X' detected on PLL input clk. This edge will be ignored.");
                    $display("Time: %0t  Instance: %m", $time);
                end
                else if ((clk === 1'b1) && first_rising_edge)
                begin
                    first_rising_edge <= 0;
                    tmp_cout <= clk;
                end
                else if ((first_rising_edge == 0) && (clk_last_valid_value !== clk))
                begin
                    if (count < modulus)
                        count <= count + 1;
                    else
                    begin
                        count <= 1;
                        tmp_cout <= ~tmp_cout;
                    end
                end
            end
        end
        clk_last_value <= clk;
        if (clk !== 1'bx)
            clk_last_valid_value <= clk;

        cout_tmp <= #(time_delay) tmp_cout;
    end

    always @(posedge clk or posedge reset)
    begin
        if (reset)
            cout <= 0;
        else
            cout <= cout_tmp;
    end

endmodule

