description:
Implement the Verilog module based on the following description.
Module R implements the boolean function u = a & ~b.

// Module S can be described by the following simulation waveform: 

If a = 1, b = 0, then u = 1.
If a = 0, b = 1, then u = 0.
If a = 0, b = 0, then u = 0.
If a = 1, b = 1, then u = 0.

// Now consider a top-level that uses two R submodules and two S submodules. The first input of all four submodules is connected to input 'a', and the second input of all four submodules is connected to 'b'. The output of the first R submodule is connected to a two-input NOR, along with the output of the first S submodule. The second pair of R and S submodules is similarly connected to an XOR gate. The output of the NOR and the XOR is connected to an AND, whose output is 'u'.

// Implement this circuit in Verilog.

module top_module(
    input a,
    input b,
    output u);

code:
module R(
    input a,
    input b,
    output u
);
    assign u = a & ~b;
endmodule

module S(
    input a,
    input b,
    output u
);
    assign u = a & ~b;
endmodule

module top_module(
    input a,
    input b,
    output u
);
    wire r1_out, r2_out, s1_out, s2_out;
    wire nor_out, xor_out;

    R r1(.a(a), .b(b), .u(r1_out));
    R r2(.a(a), .b(b), .u(r2_out));
    S s1(.a(a), .b(b), .u(s1_out));
    S s2(.a(a), .b(b), .u(s2_out));

    assign nor_out = ~(r1_out | s1_out);
    assign xor_out = r2_out ^ s2_out;

    assign u = nor_out & xor_out;
endmodule

