module mealy_machine (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter X=0, Y=1, Z=2;

    always_comb begin
        case (state)
            X: next_state = in ? Z : Y;
            Y: next_state = in ? Z : X;
            Z: next_state = in ? X : Y;
        endcase
    end

    always_comb begin
        case (state)
            X: out = 0;
            Y: out = 1;
            Z: out = 0;
        endcase
    end

endmodule

