    assign or_out = shift_reg_a | shift_reg_b;
    assign sum_out = {xor_out[2], xor_out[1] ^ and_out[3], xor_out[0] ^ and_out[2], xor_out[3] ^ or_out[3]};
    assign not_out = {~shift_reg_b, ~shift_reg_a};

