description:
Design a frequency synthesizer module that produces a synthesized clock output based on a reference clock input. The module accepts a control signal that specifies a frequency ratio and phase offset, which are used to compute a synthesized frequency ranging from 1 kHz to 100 MHz. It employs a phase-locked loop (PLL) mechanism where the synthesized frequency is derived from the reference frequency, modulated by the specified ratio and incremented within a phase accumulator. The output clock (`clk_syn`) toggles at the calculated synthesized frequency, enabling low-jitter clock generation for various applications.
module top_module(
  input clk_ref,
  input [31:0] ctrl,
  output reg clk_syn
);

code:
module top_module(
  input clk_ref,
  input [31:0] ctrl,
  output reg clk_syn
);parameter f_ref = 10_000_000; // reference frequency (10 MHz)
parameter f_min = 1_000;      // minimum synthesized frequency (1 kHz)
parameter f_max = 100_000_000; // maximum synthesized frequency (100 MHz)

// Define the frequency ratio and phase offset between the reference and synthesized frequencies
reg [31:0] ratio;
reg [31:0] phase_offset;
always @ (ctrl) begin
  ratio = ctrl[15:0]; // extract the lower 16 bits as the frequency ratio
  phase_offset = ctrl[31:16]; // extract the upper 16 bits as the phase offset
end

// Calculate the synthesized frequency based on the frequency ratio and phase offset
reg [31:0] f_syn;
always @ (posedge clk_ref) begin
  f_syn <= (f_ref * ratio) + ((phase_offset * (f_ref >> 32)) >> 32);
end

// Generate the synthesized frequency signal using a PLL
reg [31:0] phase_accumulator;
reg [31:0] phase_increment;
parameter f_clk = 100_000_000; // output clock frequency (100 MHz)
initial phase_accumulator = 0;
always @ (posedge clk_ref) begin
  phase_increment <= (f_syn * (1 << 32)) / f_clk; // Fixed calculation for phase increment
  phase_accumulator <= phase_accumulator + phase_increment;
  if (phase_accumulator >= (1 << 32)) begin
    phase_accumulator <= phase_accumulator - (1 << 32);
    clk_syn <= ~clk_syn;
  end
end

endmodule

