module washing_machine (
	input clk,
	input resetn,
	input start,
	output reg [1:0] state_out);

	parameter IDLE=2'b00, WASHING=2'b01, SPINNING=2'b10;
	reg [1:0] state, next_state;
	reg [3:0] counter;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always @(posedge clk) begin
		if (state == next_state) counter <= counter + 1;
		else counter <= 0;
	end

	always_comb begin
		case (state)
			IDLE: next_state = start ? WASHING : IDLE;
			WASHING: next_state = (counter == 4'b1111) ? SPINNING : WASHING;
			SPINNING: next_state = (counter == 4'b1111) ? IDLE : SPINNING;
			default: next_state = IDLE;
		endcase
	end

	always @(state) begin
		case (state)
			IDLE: state_out = 2'b00;
			WASHING: state_out = 2'b01;
			SPINNING: state_out = 2'b10;
			default: state_out = 2'b00;
		endcase
	end
endmodule

