module top_module(
    input clk,
    input rst,
    input wr_en,
    input [3:0] wr_data,
    input rd_en,
    output [3:0] rd_data,
    output full,
    output empty
);reg [3:0] fifo [0:3];
reg [1:0] wr_ptr;
reg [1:0] rd_ptr;
wire [1:0] next_wr_ptr;
wire [1:0] next_rd_ptr;

assign full = (next_wr_ptr == rd_ptr);
assign empty = (wr_ptr == rd_ptr);

// Write pointer logic
always @ (posedge clk) begin
    if (rst) begin
        wr_ptr <= 2'b00;
    end else if (wr_en && !full) begin
        wr_ptr <= next_wr_ptr;
    end
end

assign next_wr_ptr = (wr_ptr == 2'b11) ? 2'b00 : wr_ptr + 1;

// Read pointer logic
always @ (posedge clk) begin
    if (rst) begin
        rd_ptr <= 2'b00;
    end else if (rd_en && !empty) begin
        rd_ptr <= next_rd_ptr;
    end
end

assign next_rd_ptr = (rd_ptr == 2'b11) ? 2'b00 : rd_ptr + 1;

// FIFO memory
always @ (posedge clk) begin
    if (rst) begin
        integer i;
        for (i = 0; i < 4; i = i + 1) begin
            fifo[i] <= 4'b0000; // Reset individual FIFO entries
        end
    end else if (wr_en && !full) begin
        fifo[wr_ptr] <= wr_data;
    end
end

assign rd_data = fifo[rd_ptr];

endmodule

