module top_module(

    input CLK,
    input nrst,

    input [3:0] btn,

    output reg [3:0] db_btn
    );reg [20:0] count;		
	wire in = |btn;			
	wire max = count[20];	


	always@(posedge CLK) begin
		if(!nrst)
			count <= 0;
		else
			case({in, max})
				2'b10: count <= count + 1;
				2'b01: count <= count + 1;
				2'b00: count <= 0;
			endcase
	end


	always@(posedge CLK) begin
		if(!nrst) begin
			db_btn <= 0;
		end
		else begin
			case({in, max})
				2'b11: db_btn <= btn;
				2'b00: db_btn <= btn;
			endcase
		end
	end

endmodule

