module top_module(
out     ,  
finished,  
enable  ,  
clk     ,  
reset      
);`ifdef SIMONLY
  parameter N = 6;  
`else
  parameter N = 23;  
`endif


  output reg finished;
  output reg [N-1:0] out;

  input enable, clk, reset;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      out <= {N{1'b0}};
      finished <= 0;
    end
    else if (out[N-1]==1) begin
        finished <= 1'b1;
    end
    else if (enable && (!finished)) begin
      out <= out + 1;
    end
  end

endmodule

