module top_module(
    input clk,
    input rst,
    input [1:0] op,
    input signed [15:0] a,
    input signed [15:0] b,
    output reg valid,
    output reg error,
    output reg signed [15:0] result
);reg signed [15:0] temp_result;

always @(posedge clk) begin
    if (rst) begin
        valid <= 0;
        error <= 0;
        result <= 0;
        temp_result <= 0;
    end else begin
        case(op)
            2'b00: temp_result <= a + b; // addition
            2'b01: temp_result <= a - b; // subtraction
            2'b10: temp_result <= a * b; // multiplication
            2'b11: begin                  // division
                if (b == 0) begin
                    error <= 1;
                end else begin
                    temp_result <= a / b;
                end
            end
        endcase

        result <= temp_result;
        valid <= 1;
        error <= 0;
    end
end

