module top_module(
	input clk, sleep,

	output reg end_sleep
		);reg [3:0] counter;	

	always @(posedge clk) begin

		if (!sleep) begin
			counter <= 0;
			end_sleep <= 0;
		end

		else if (counter == 4'b1111) begin
			end_sleep <= 1;
		end

		else if (sleep) begin
			counter <= counter + 1'b1;
		end

		else if (end_sleep == 1) begin
			end_sleep <= 0;
			counter <= 0;
		end

	end

endmodule

