  if (reset == 1'b0) begin
    AC <= 4'b0;
    Q <= 4'b0;
    M <= 2'b0;
    P <= 8'b0;
  end else begin
    // Booth's algorithm
    M <= {B[3], B[3:2]};
    case (M)
      2'b00: Q <= {Q[2:0], 1'b0};
      2'b01: begin
        AC <= AC + A;
        Q <= {Q[2:0], 1'b1};
