module top_module(input clk,rst,input [31:0] data,input[14:0] addr,input write,output [2:0] outTag, output outValid);reg [31:0] mem [4095:0];
    reg [2:0] tag [4095:0];
    reg valid [4095:0];

    assign outTag = (rst == 0) ? tag[addr[11:0]] : 2'b00;
    assign outValid = valid[addr[11:0]];

    always @(posedge clk,posedge rst) begin
        if (rst) begin: RST
            integer i;
            for (i = 0;i <= 4096;i = i+1) begin
                valid[i] = 1'b0;
            end
        end
        else if(write) begin
            mem[addr[11:0]] <= data;
            tag[addr[11:0]] <= addr[14:12];
            valid[addr[11:0]] <= 1'b1;
        end
    end

endmodule

module reg_file_16bit(clk, reset, write_enable, write_addr, write_data, read_addr, read_data);
    input clk;
    input reset;
    input write_enable;
    input [1:0] write_addr;
    input [15:0] write_data;
    input [1:0] read_addr;
    output reg [15:0] read_data;

    reg [15:0] registers [3:0];

    always @(posedge clk) begin
        if (reset) begin
            registers[0] <= 16'b0;
            registers[1] <= 16'b0;
            registers[2] <= 16'b0;
            registers[3] <= 16'b0;
        end
        else if (write_enable) begin
            registers[write_addr] <= write_data;
        end
    end

    always @(*) begin
        read_data = registers[read_addr];
    end
endmodule

