    task testcase003;

        begin
            test_num = 3;
            $display("Testcase %03d: All '0's Input", test_num);
            reset_dut();
            data = 8'hFF;
            @(posedge clk);
            data = 8'h00;
            @(posedge clk);
            #1;

            check_outputs(4'd0);
        end
        endtask

    task testcase004;

