            data = 8'hFF;
            @(posedge clk);
            data = 8'h80;
            @(posedge clk);
            data = 8'h80;
            @(posedge clk);
            #1;

            check_outputs(4'd10);
        end
        endtask

    task testcase008;

        begin
            test_num = 8;
            $display("Testcase %03d: Reset mid-stream", test_num);
            reset_dut();
            data = 8'h80;
            @(posedge clk);
            data = 8'h80;
            @(posedge clk);
            reset = 1;
            @(posedge clk);
            reset = 0;
            #1;

            check_outputs(4'd0);
        end
        endtask

    task testcase009;

        begin
            test_num = 9;
            $display("Testcase %03d: All-ones then break with MSB=0", test_num);
            reset_dut();
            data = 8'hFF;
