  assign ADDRB = write_pointer;
  assign DOUTB = memory[ADDRB];

  always @(posedge clk) begin
    if (ENB) begin
      if (E) begin
        memory[write_pointer] <= din;
        write_pointer <= write_pointer + 1;
      end else begin
        read_pointer <= read_pointer + 1;
      end
    end
  end

endmodule

