reg [31:0] douta_reg;

always @(posedge clka) begin
    if (ena) begin
        if (wea == 1'b1) begin
            cache_mem[addra] <= dina;
        end else begin
            douta_reg <= cache_mem[addra];
        end
    end
end

assign douta = douta_reg;

