description:
Design a keypad scanner circuit that scans a 4x4 matrix keypad. The module uses a clock input to sequentially activate one row at a time while checking the column inputs for key presses. Depending on which column input is high, the corresponding row output is set, enabling the identification of key presses in the matrix. The circuit outputs a 4-bit wide signal representing the currently active row.
module top_module(
    input clk,
    input [3:0] col,
    output reg [3:0] row
);

code:
module top_module(
    input clk,
    input [3:0] col,
    output reg [3:0] row
);reg [3:0] row_temp;

always @(posedge clk) begin
    row_temp <= 4'b1110;
    if (col[0] == 1) row_temp <= 4'b1101;
    if (col[1] == 1) row_temp <= 4'b1011;
    if (col[2] == 1) row_temp <= 4'b0111;
    if (col[3] == 1) row_temp <= 4'b1110;
end

always @(posedge clk) begin
    row <= row_temp;
end

endmodule

module top_module (
        input clk,
        input areset,
        input power_on,
        input power_off,
        input temp_reached,
        output reg ac);parameter Off=2'b00, Cooling=2'b01, Idle=2'b10;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Off;
		else begin
			case (state)
				Off: state <= power_on ? Cooling : Off;
				Cooling: state <= temp_reached ? Idle : Cooling;
				Idle: state <= power_off ? Off : Idle;
			endcase
		end
	end

	assign ac = (state == Cooling);

endmodule

module priority_encoder (
	input [3:0] in,
	output reg [1:0] out);

	always @(*) begin
		case (1'b1)
			in[3]: out = 2'b11;
			in[2]: out = 2'b10;
			in[1]: out = 2'b01;
			in[0]: out = 2'b00;
			default: out = 2'b00;
		endcase
	end

endmodule

